UPDATE torn_stock_notice_audit
SET send_status = 'SENT',
    sent_at = #{businessNow},
    update_time = #{businessNow}
WHERE deleted = 0
  AND send_status = 'SENDING'
  AND claim_token = #{claimToken}
  AND id IN

    #{id}

UPDATE torn_stock_notice_audit SET payload_snapshot = source.payload_snapshot, payload_hash = source.payload_hash, update_time = #{businessNow} FROM (VALUES
(CAST(#{cmd.noticeId} AS BIGINT), CAST(#{cmd.payloadSnapshot} AS jsonb), #{cmd.payloadHash}, CAST(#{cmd.claimToken} AS VARCHAR(64)))
) AS source(notice_id, payload_snapshot, payload_hash, claim_token) WHERE torn_stock_notice_audit.id = source.notice_id AND torn_stock_notice_audit.deleted = 0 AND torn_stock_notice_audit.send_status = 'SENDING' AND torn_stock_notice_audit.claim_token = source.claim_token
